import aspire.*;

// Java-authored AppHost (preview): a Spring Boot notes API and PostgreSQL.
// The Aspire SDK in .aspire/modules is generated by `aspire restore`.
public class AppHost {
    public static void main(String[] args) throws Exception {
        IDistributedApplicationBuilder builder = Aspire.createBuilder(null);

        // PostgreSQL container plus a database. Referencing it injects
        // NOTESDB_JDBCCONNECTIONSTRING, NOTESDB_USERNAME, and NOTESDB_PASSWORD.
        var db = builder.addPostgres("pg").addDatabase("notesdb");

        // Spring Boot runs natively through its Maven wrapper (spring-boot:run).
        // Aspire supplies SERVER_PORT and the OTEL_* settings.
        builder.addSpringBootApp("api", "./api")
            .withReference(db)
            .waitFor(db)
            .withHttpHealthCheck(new WithHttpHealthCheckOptions().path("/actuator/health"))
            .withExternalHttpEndpoints();

        builder.build().run(null);
    }
}
